  if (!Array.isArray(values) || !values.every(Number.isFinite)) {
    throw new TypeError('values must contain finite numbers');
  }
  if (values.length === 0) return null;
  let bestSum = 0;
  let bestStart = 0;
  let bestEnd = 0;
  for (let start = 0; start < values.length; start += 1) {
