      const length = end - start + 1;
      const bestLength = bestEnd - bestStart + 1;
      if (sum < bestSum ||
          (sum === bestSum && (length < bestLength ||
          (length === bestLength && start < bestStart)))) {
        bestSum = sum;
        bestStart = start;
        bestEnd = end;
      }
    }
  }
  return { sum: bestSum, start: bestStart, end: bestEnd };
}

module.exports = { lowestSegment };
