'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['lowestSegment']);
const { lowestSegment } = api;

assert.strictEqual(lowestSegment([]), null);
assert.deepStrictEqual(lowestSegment([5]), { sum: 5, start: 0, end: 0 });
assert.deepStrictEqual(lowestSegment([-5]), { sum: -5, start: 0, end: 0 });
assert.deepStrictEqual(lowestSegment([4, 2, 7]), { sum: 2, start: 1, end: 1 });
assert.deepStrictEqual(lowestSegment([3, -4, 2, -5, 6]), { sum: -7, start: 1, end: 3 });
assert.deepStrictEqual(lowestSegment([0, 0, 0]), { sum: 0, start: 0, end: 0 });
assert.deepStrictEqual(lowestSegment([2, -2, 2, -2]), { sum: -2, start: 1, end: 1 });
assert.deepStrictEqual(lowestSegment([-1, 0]), { sum: -1, start: 0, end: 0 });
assert.deepStrictEqual(lowestSegment([1, -1]), { sum: -1, start: 1, end: 1 });

const orderSensitive = [1e20, -1e20, -1];
assert.deepStrictEqual(lowestSegment(orderSensitive), { sum: -100000000000000000000, start: 1, end: 2 });

const values = [2, -3, 1];
const snapshot = values.slice();
lowestSegment(values);
assert.deepStrictEqual(values, snapshot);

for (const bad of [null, {}, '1,2', [1, NaN], [1, Infinity], [1, '2']]) {
  assert.throws(() => lowestSegment(bad), TypeError);
}

